-- =============================================================================
-- ShilpSetu — Prototype Dataset Seed Migration
-- File: database/seeds/002_prototype_dataset.sql
-- Description: Imports the complete prototype dataset into Supabase PostgreSQL:
--              - 23 users (artisans & buyers)
--              - 20 artisans (profiles, locations, languages, ratings)
--              - 150 products (catalogue details, categories, prices, tags, JSONB)
--              - 150 inventory records (available quantities, production capacities)
--              - 2 quote requests (bulk buyer natural language requirements)
--              - 5 quote request artisan matches (multi-artisan pool matching)
-- Source: shilpsetu_dataset
-- Safety: Safe & non-destructive; uses ON CONFLICT DO NOTHING to prevent overwrites.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. USERS (23 records)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 2. ARTISANS (20 records)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 3. PRODUCTS (150 records)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 4. INVENTORY (150 records)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 5. QUOTE REQUESTS (2 records)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 6. QUOTE REQUEST ARTISANS (5 records)
-- Note on dataset quality: Quote 05d89ac2-7903-5d06-95cd-53267ec9e853 has two allocations
-- for artisan c6a3bddc-b392-51f7-a3f8-99be6187e98b (37 + 39 = 76 units).
-- Drop legacy unique constraint if present from previous schema revisions
ALTER TABLE quote_request_artisans DROP CONSTRAINT IF EXISTS uq_quote_request_artisan;

ON CONFLICT DO NOTHING;
